INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-15', 15, '第15課 听力训练', 'listening/listening-lesson-15.mp3', 162772, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn15-s1', 'listen-15', 1, 'tf', '听录音，根据录音中的内容判断对错。对的画（○），错的画（×）。', 12732, 85171, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s1-q1', 'lsn15-s1', 1, '伊藤さんはアイスコーヒーを注文しました。', '[]'::jsonb, '○');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s1-q2', 'lsn15-s1', 2, '男の人は、日曜日いつも家で家事をします。', '[]'::jsonb, '×');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s1-q3', 'lsn15-s1', 3, '女の人は、これから資料を作ります。', '[]'::jsonb, '×');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l1', 'lsn15-s1', 1, '男', 13032, 16400, '暑いですね。何か飲みましょうか。', '男：真热啊。喝点什么吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l2', 'lsn15-s1', 2, '女', 16938, 21104, 'いいですね。私、コーラ。伊藤さんは？', '女：好啊。我要可乐。伊藤你呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l3', 'lsn15-s1', 3, '男', 22589, 25306, '僕、アイスコーヒーがいいですね。', '男：我要冰咖啡。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l4', 'lsn15-s1', 4, '男', 30258, 37977, '日曜日はいつも何をしますか。', '男：周日你通常做什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l5', 'lsn15-s1', 5, '女', 39062, 40702, '家で家事をしますよ。', '女：在家做家务。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l6', 'lsn15-s1', 6, '男', 41502, 42242, 'えらいですね。', '男：真了不起。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l7', 'lsn15-s1', 7, '女', 42595, 43465, '田中さんは？', '女：田中你呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l8', 'lsn15-s1', 8, '男', 43954, 50270, '僕は普段、仕事が忙しいので、日曜日はいつも家で寝ます。', '男：我平时工作忙，所以周日总是在家睡觉。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l9', 'lsn15-s1', 9, '女', 51008, 52448, 'へえ、ずっと？', '女：哦，一直睡？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l10', 'lsn15-s1', 10, '男', 53031, 53961, 'お昼頃まで。', '男：睡到中午左右。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l11', 'lsn15-s1', 11, '女', 54829, 57247, 'すごいですね。それからは？', '女：真厉害。那之后呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l12', 'lsn15-s1', 12, '男', 57862, 61901, 'それからはゆっくりご飯を食べます。', '男：之后慢慢吃饭。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l13', 'lsn15-s1', 13, '男', 66858, 73536, '明日の資料、もう作りました？', '男：明天的资料已经做好了吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l14', 'lsn15-s1', 14, '女', 74319, 75331, 'はい。こちらです。', '女：做好了。在这里。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l15', 'lsn15-s1', 15, '男', 76122, 76752, 'ありがとう。', '男：谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l16', 'lsn15-s1', 16, '女', 77266, 80485, 'これで大丈夫なら、部長にも送りましょうか。', '女：如果这样可以的话，也给部长发一份吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s1-l17', 'lsn15-s1', 17, '男', 81371, 84471, 'そうですね。お願いします。', '男：好啊。麻烦你了。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn15-s2', 'listen-15', 2, 'text', '听录音，根据录音中的内容回答问题（用日语输入，标点可省略）。背景：男生和女生在对话。', 99792, 155819, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s2-q1', 'lsn15-s2', 1, '女の人は昨日何を買いましたか。', '[]'::jsonb, '何も買いませんでした|何も買わなかった|何も買いません');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s2-q2', 'lsn15-s2', 2, '男の人は手伝いましたか。', '[]'::jsonb, 'いいえ|いいえ手伝いませんでした|手伝いませんでした');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn15-s2-q3', 'lsn15-s2', 3, '男の人は女の人といつ映画を見ますか。', '[]'::jsonb, '明日です|明日');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l1', 'lsn15-s2', 1, '男', 100092, 104081, '昨日、何をしましたか。', '男：昨天做了什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l2', 'lsn15-s2', 2, '女', 104461, 111091, '午前は、博物館に行きました。午後はショッピング。', '女：上午去了博物馆，下午购物。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l3', 'lsn15-s2', 3, '男', 111767, 116252, 'いっぱい買いましたか。', '男：买了很多吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l4', 'lsn15-s2', 4, '女', 117037, 122672, 'ううん、何も買いませんでした。', '女：没有，什么都没买。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l5', 'lsn15-s2', 5, '男', 126211, 131114, 'あ、持ちましょうか。', '男：啊，我帮你拿吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l6', 'lsn15-s2', 6, '女', 131460, 138605, 'ありがとうございます。でも、大丈夫です。どうも。', '女：谢谢。不过不用了。谢谢。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l7', 'lsn15-s2', 7, '女', 141115, 143155, '一緒に映画を見ましょうか。', '女：一起看电影吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l8', 'lsn15-s2', 8, '男', 143156, 146154, 'いいですね。いつ行きますか。', '男：好啊。什么时候去？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l9', 'lsn15-s2', 9, '女', 146700, 148460, '今日の午後はどうですか。', '女：今天下午怎么样？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l10', 'lsn15-s2', 10, '男', 149341, 150840, '今日はちょっと。明日なら大丈夫ですが。', '男：今天有点……明天的话可以。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn15-s2-l11', 'lsn15-s2', 11, '女', 151573, 155119, 'じゃ、そうしましょう。', '女：那就这么定了。');
